 @Autowired ExperienceManagementService management;
 @BeforeEach void consumer(){clientTenant=UUID.randomUUID();clientActor=UUID.randomUUID();clientSpace=UUID.randomUUID();db.update("INSERT INTO tenants(id,name) VALUES (?,'合成使用企业')",clientTenant);db.update("INSERT INTO accounts(id,email,display_name,password_hash) VALUES (?,?,'合成使用者','unused')",clientActor,clientActor+"@consumer.test");db.update("INSERT INTO tenant_memberships(tenant_id,account_id,role) VALUES (?,?,'MEMBER')",clientTenant,clientActor);db.update("INSERT INTO workspaces(id,tenant_id,owner_id,name,kind) VALUES (?,?,?,'合成使用空间','SHARED')",clientSpace,clientTenant,clientActor);db.update("INSERT INTO workspace_members(tenant_id,workspace_id,account_id) VALUES (?,?,?)",clientTenant,clientSpace,clientActor);db.update("INSERT INTO governance_capabilities(tenant_id,account_id,workspace_id,capability,granted_by) VALUES (?,?,?,'EXPERIENCE_MAINTAIN',?)",clientTenant,clientActor,clientSpace,clientActor);}
