 TaskContextService.Request request(String action,GeneralExperienceAdmissionService.Receipt r,Integer offset,UUID key,String decision,String conditions,String adjustments){return new TaskContextService.Request(action,null,null,offset,r==null?null:r.entryId(),r==null?null:r.versionId(),null,key,decision,conditions,adjustments);}
 tools.jackson.databind.JsonNode call(ConversationService.Job t,TaskContextService.Request r){return new tools.jackson.databind.json.JsonMapper().valueToTree(context.context(t.id(),t.token(),r)).get("result");}
 tools.jackson.databind.JsonNode search(ConversationService.Job t){return call(t,new TaskContextService.Request("general_experience_search",null,method().title(),0,null,null,null,null,null,null,null));}
 tools.jackson.databind.JsonNode read(ConversationService.Job t,GeneralExperienceAdmissionService.Receipt r,int offset){return call(t,request("general_experience_read",r,offset,null,null,null,null));}
 tools.jackson.databind.JsonNode use(ConversationService.Job t,GeneralExperienceAdmissionService.Receipt r,UUID key,String decision){return call(t,request("general_experience_use",r,null,key,decision,"当前输入、场景和工具满足限制","只调整本任务展示格式"));}
 void finish(ConversationService.Job t,String reply){agents.finish(t,new AgentResult("1.4","0.11.0",t.id(),t.token(),"AGENT","verification","synthetic-general-context",reply,List.of(),List.of(),List.of(),1,null,List.of(),List.of(),List.of()));}
 void denied(int status,Runnable r){assertEquals(status,assertThrows(IdentityException.class,r::run).status);}

 GeneralExperienceSuggestionService.Change change(GeneralExperienceAdmissionService.Receipt g,UUID key){return new GeneralExperienceSuggestionService.Change(key,g.versionId(),clientSpace,"ADAPTATION","本企业需要先核对回执覆盖期间，再判断结论；没有期间依据时停止推断。private-suggestion");}
 GeneralExperienceSuggestionService.Suggestion submit(GeneralExperienceAdmissionService.Receipt g){return suggestions.submit(clientActor,clientTenant,g.entryId(),change(g,UUID.randomUUID()));}
 Job localClaim(){var j=queue.claim(clientTenant);assertNotNull(j);return j;}
 Result localResult(Job j,String outcome,UUID target){var evidence=j.inputs().stream().map(i->new Evidence(i.id(),i.text().substring(0,Math.min(700,i.text().length())))).toList();var c=new Candidate(target,"核对覆盖期间的企业方法","比较口径后核对执行回执",List.of("先核对期间和口径，再解读工具回执"),List.of("有期间和执行证据"),List.of("没有依据时停止推断"),List.of("期间"),evidence);return new Result("1.0","synthetic-v1","live",j.id(),j.lease(),j.source(),false,outcome,outcome.equals("QUALIFIED")?null:"QUALITY_NOT_ESTABLISHED",outcome.equals("QUALIFIED")?c:null,outcome.equals("QUALIFIED")?new Review(Map.of("grounded","PASS","reusable","PASS","bounded","PASS","privacySafe","PASS","novel","PASS"),"FEEDBACK_CORRECTION",evidence):null,List.of(new Stage("EXTRACT","synthetic",1,10L,2L),new Stage("VERIFY","synthetic",1,10L,2L)));}
 ExperienceAdmissionService.Receipt admitLocal(GeneralExperienceAdmissionService.Receipt g){submit(g);var j=localClaim();queue.dispatched(j,descriptor());queue.complete(localResult(j,"QUALIFIED",null));return admission.admit(j.id());}
 Object readLocal(ConversationService.Job t,ExperienceAdmissionService.Receipt l){return call(t,new TaskContextService.Request("experience_read",null,null,0,l.entryId(),l.versionId(),null,null,null,null,null));}
 boolean localCurrent(UUID version){return db.queryForObject("SELECT experience_general_dependencies_current(?,?)",Boolean.class,clientTenant,version);}
 @Test void explicitScopePrivateIdempotentInputAndFixedGeneralVersion(){
  seed();var g=publish(method());UUID key=UUID.randomUUID();var a=suggestions.submit(clientActor,clientTenant,g.entryId(),change(g,key));assertEquals(a,suggestions.submit(clientActor,clientTenant,g.entryId(),change(g,key)));assertEquals("WAITING",a.state());assertNull(a.resultVersionId());assertEquals(0,db.queryForObject("SELECT count(*) FROM experience_entries WHERE tenant_id=?",Integer.class,clientTenant));
  assertEquals("EXPERIENCE_SUGGESTION_PENDING",assertThrows(IdentityException.class,()->submit(g)).code);var page=suggestions.list(clientActor,clientTenant,g.entryId(),g.versionId(),true);assertTrue(page.enabled());assertEquals(List.of(clientSpace),page.scopes().stream().map(ExperienceManagementService.Scope::id).toList());assertFalse(new tools.jackson.databind.json.JsonMapper().writeValueAsString(page).contains("private-suggestion"));
  var wrong=new GeneralExperienceSuggestionService.Change(key,g.versionId(),clientSpace,"FEEDBACK","other");assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(IdentityException.class,()->suggestions.submit(clientActor,clientTenant,g.entryId(),wrong)).code);
  var j=localClaim();assertTrue(j.existing().isEmpty());assertEquals(Set.of("SOURCE_EXCERPT","FEEDBACK"),new HashSet<>(j.inputs().stream().map(Input::kind).toList()));String text=j.inputs().toString();for(String secret:List.of("private-prompt","private-reply",task.toString(),owner.toString(),space.toString()))assertFalse(text.contains(secret),secret);
 }
