 @Test void httpSuggestionRequiresCustomerSessionAndCsrfAndNeverReturnsPrivateText()throws Exception{
  seed();var g=publish(method());db.update("UPDATE accounts SET password_hash=? WHERE id=?",passwords.encode("synthetic-suggestion-password"),clientActor);var http=java.net.http.HttpClient.newBuilder().cookieHandler(new java.net.CookieManager(null,java.net.CookiePolicy.ACCEPT_ALL)).build();var json=new tools.jackson.databind.json.JsonMapper();String base="http://127.0.0.1:"+port;var csrf=json.readTree(http.send(java.net.http.HttpRequest.newBuilder(java.net.URI.create(base+"/api/v1/auth/csrf")).GET().build(),java.net.http.HttpResponse.BodyHandlers.ofString()).body());
  var login=http.send(java.net.http.HttpRequest.newBuilder(java.net.URI.create(base+"/api/v1/auth/login")).header(csrf.get("headerName").asString(),csrf.get("token").asString()).header("Content-Type","application/json").POST(java.net.http.HttpRequest.BodyPublishers.ofString(json.writeValueAsString(Map.of("email",clientActor+"@consumer.test","password","synthetic-suggestion-password")))).build(),java.net.http.HttpResponse.BodyHandlers.ofString());assertEquals(200,login.statusCode());csrf=json.readTree(http.send(java.net.http.HttpRequest.newBuilder(java.net.URI.create(base+"/api/v1/auth/csrf")).GET().build(),java.net.http.HttpResponse.BodyHandlers.ofString()).body());
  String path=base+"/api/v1/tenants/"+clientTenant+"/general-experiences/"+g.entryId()+"/suggestions";var req=java.net.http.HttpRequest.newBuilder(java.net.URI.create(path)).header("Content-Type","application/json").POST(java.net.http.HttpRequest.BodyPublishers.ofString(json.writeValueAsString(change(g,UUID.randomUUID()))));assertEquals(403,http.send(req.build(),java.net.http.HttpResponse.BodyHandlers.ofString()).statusCode());var response=http.send(req.header(csrf.get("headerName").asString(),csrf.get("token").asString()).build(),java.net.http.HttpResponse.BodyHandlers.ofString());assertEquals(200,response.statusCode(),response.body());assertFalse(response.body().contains("private-suggestion"));assertEquals("WAITING",json.readTree(response.body()).get("state").asString());
  var page=http.send(java.net.http.HttpRequest.newBuilder(java.net.URI.create(path+"?version="+g.versionId())).GET().build(),java.net.http.HttpResponse.BodyHandlers.ofString());assertEquals(200,page.statusCode());assertTrue(page.headers().firstValue("cache-control").orElseThrow().contains("no-store"));assertFalse(page.body().contains("private-suggestion"));assertFalse(json.readTree(page.body()).get("enabled").asBoolean());assertTrue(json.readTree(page.body()).get("canSubmit").asBoolean());var platform=http.send(java.net.http.HttpRequest.newBuilder(java.net.URI.create(base+"/api/platform-admin/v1/experience-library/"+g.entryId())).GET().build(),java.net.http.HttpResponse.BodyHandlers.ofString());assertEquals(401,platform.statusCode());
 }

 @Test void actualHarnessChecksPrivateProposalInFreshStagesButVerificationCannotAdmit()throws Exception{
  seed();var g=publish(method());var a=submit(g);var j=localClaim();var root=java.nio.file.Path.of("").toAbsolutePath();if(root.endsWith("api"))root=root.getParent().getParent();String token="synthetic-suggestion-012345678901234567890";
  var engine=new ProcessBuilder("node",root.resolve("engine/tests/fixtures/experience-dispatch-server.mjs").toString(),token,"suggestion").redirectError(ProcessBuilder.Redirect.INHERIT).start();
  try(var pool=Executors.newSingleThreadExecutor();var lines=new java.io.BufferedReader(new java.io.InputStreamReader(engine.getInputStream()))){
   var runtime=new ExperienceAnalysisRuntime(pool.submit(lines::readLine).get(5,TimeUnit.SECONDS),token,"verification");var worker=new ExperienceAnalysisWorker(queue,runtime,admission,false);try{worker.execute(j);}finally{worker.stop();}
   var result=runtime.recover(j,runtime.preflight().engineVersion());assertEquals("QUALIFIED",result.outcome());assertNull(result.candidate().targetVersionId());assertEquals("FEEDBACK_CORRECTION",result.review().basis());assertEquals(2,result.stages().size());assertEquals("FAILED",state(j));assertEquals("EXPERIENCE_VERIFICATION_ONLY",db.queryForObject("SELECT error_code FROM experience_analysis_items WHERE source_id=?",String.class,a.id()));assertNull(db.queryForObject("SELECT content::text FROM general_experience_suggestions WHERE id=?",String.class,a.id()));assertEquals(0,db.queryForObject("SELECT count(*) FROM experience_entries WHERE tenant_id=?",Integer.class,clientTenant));assertTrue(available(g.versionId()));
  }finally{engine.destroy();if(!engine.waitFor(3,TimeUnit.SECONDS))engine.destroyForcibly();}
 }

